insert into public.survey_minor_counts (workspace_id, survey_id, count_date, count)
select s.workspace_id, s.survey_id, (now() at time zone 'Asia/Tokyo')::date - v.days_ago, v.count
from _seed s, (values
  (11, 1),
  (12, 1),
  (13, 1),
  (15, 1),
  (17, 1),
  (18, 1),
  (19, 1),
  (20, 1),
  (29, 1)
) as v(days_ago, count);

